/// <summary>
/// A data cleanup rule: delete records older than a number of days, or empty a table.
/// In all companies or in the companies selected for the rule.
/// </summary>
public class BDRCleanupRule extends common
{
}

Method.Source:
    public void initValue()
    {
        super();

        this.IsActive = NoYes::Yes;
        this.AllCompanies = NoYes::Yes;
        this.KeepDays = 90;
        this.DeleteRelated = NoYes::Yes;
    }

    public boolean validateWrite()
    {
        boolean ret = super();
        TableId tableId = tableName2Id(this.TableName);
        DictTable dictTable = tableId ? new DictTable(tableId) : null;

        if (!dictTable)
        {
            return checkFailed(strFmt("@BDR:ErrInvalidTable", this.TableName));
        }

        if (!BDRTaskTypeDataCleanup::isTableAllowed(dictTable))
        {
            ret = checkFailed(strFmt("@BDR:ErrTableNotAllowed", this.TableName, dictTable.tableGroup()));
        }

        if (this.CleanupMode == BDRCleanupMode::DeleteOlderThan && !BDRTaskTypeDataCleanup::hasCreatedDateTime(tableId))
        {
            ret = checkFailed(strFmt("@BDR:ErrNoCreatedDateTime", this.TableName));
        }

        if (this.CleanupMode == BDRCleanupMode::DeleteOlderThan && this.KeepDays < 1)
        {
            ret = checkFailed(strFmt("@BDR:ErrKeepDaysPositive", this.TableName));
        }

        return this.validateOtherRules() && ret;
    }

    public void insert()
    {
        // The same rule as update(): Truncate and shared tables are always for all companies (also for copied rows).
        if (!this.canChooseCompanies())
        {
            this.AllCompanies = NoYes::Yes;
        }

        super();
    }

    public void update()
    {
        if (!this.canChooseCompanies())
        {
            this.AllCompanies = NoYes::Yes;
        }

        super();

        // All companies replaces the list of selected companies.
        if (this.AllCompanies)
        {
            BDRSetupCompany::deleteFor(this);
        }
    }

/// <summary>
/// The companies this row applies to.
/// </summary>
/// <returns>A set of company IDs.</returns>
public Set companies()
{
    return BDRSetupCompany::companies(this);
}

/// <summary>
/// The selected companies; empty when the row is for all companies.
/// </summary>
public display Description companyScope()
{
    return BDRSetupCompany::scope(this);
}

    /// <summary>
    /// Checks whether the table of the row is shared by all companies.
    /// </summary>
    /// <returns>True for a table that is not saved per company.</returns>
    public boolean isSharedTable()
    {
        TableId tableId = tableName2Id(this.TableName);

        return tableId && !new DictTable(tableId).dataPrCompany();
    }

/// <summary>
/// Companies can be chosen to delete records of a table that is saved per company.
/// Truncating a table always empties it for all companies.
/// </summary>
/// <returns>True if the rule can be limited to selected companies.</returns>
public boolean canChooseCompanies()
{
    return this.TableName && !this.isSharedTable() && this.CleanupMode != BDRCleanupMode::Truncate;
}

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        if (_fieldId == fieldNum(BDRCleanupRule, TableName) || _fieldId == fieldNum(BDRCleanupRule, CleanupMode))
        {
            if (!this.canChooseCompanies())
            {
                this.AllCompanies = NoYes::Yes;
            }

            if (this.CleanupMode == BDRCleanupMode::Truncate)
            {
                this.DeleteRelated = NoYes::No;
            }

            // Days to keep only apply when older records are deleted.
            if (this.CleanupMode != BDRCleanupMode::DeleteOlderThan)
            {
                this.KeepDays = 0;
            }
            else if (!this.KeepDays)
            {
                this.KeepDays = 90;
            }
        }
    }

    /// <summary>
    /// Truncating a table excludes every other rule of that table; the other rules of a table
    /// must not cover the same companies.
    /// </summary>
    /// <returns>True if the rule fits the other rules of its table.</returns>
    public boolean validateOtherRules()
    {
        BDRCleanupRule other;
        boolean ret = true;

        while select other
            where other.EnvironmentId == this.EnvironmentId
                && other.TableName == this.TableName
                && other.RecId != this.RecId
        {
            if (this.CleanupMode == BDRCleanupMode::Truncate || other.CleanupMode == BDRCleanupMode::Truncate)
            {
                return checkFailed(strFmt("@BDR:ErrTruncateExclusive", this.TableName));
            }

            if (this.AllCompanies || other.AllCompanies)
            {
                ret = checkFailed(strFmt("@BDR:ErrCleanupAllCompaniesOverlap", this.TableName, enum2Str(other.CleanupMode))) && ret;
                continue;
            }

            SetEnumerator enumerator = this.companies().getEnumerator();
            Set otherCompanies = other.companies();

            while (enumerator.moveNext())
            {
                if (otherCompanies.in(enumerator.current()))
                {
                    ret = checkFailed(strFmt("@BDR:ErrCleanupCompaniesOverlap", this.TableName, enum2Str(other.CleanupMode), enumerator.current())) && ret;
                }
            }
        }

        return ret;
    }

    /// <summary>
    /// Checks whether a company can be added to this rule without overlapping another rule of the table.
    /// </summary>
    /// <param name = "_company">The company.</param>
    /// <returns>True if no other rule of the table covers the company.</returns>
    public boolean allowsCompany(DataAreaId _company)
    {
        BDRCleanupRule other;

        while select other
            where other.EnvironmentId == this.EnvironmentId
                && other.TableName == this.TableName
                && other.RecId != this.RecId
        {
            if (other.AllCompanies || other.CleanupMode == BDRCleanupMode::Truncate || other.companies().in(_company))
            {
                return checkFailed(strFmt("@BDR:ErrCleanupCompaniesOverlap", this.TableName, enum2Str(other.CleanupMode), _company));
            }
        }

        return true;
    }
